-- Executed with the application owner; no cross-service references.
CREATE TABLE IF NOT EXISTS app.schema_migrations(id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- A constrained domain avoids NUMERIC(p,s) silently rounding before validation.
CREATE DOMAIN app.exact_decimal AS NUMERIC CHECK (
 VALUE <> 'NaN'::numeric AND abs(VALUE) < 1000000000000000000 AND trunc(VALUE,10)=VALUE
);
CREATE TABLE app.households(id TEXT PRIMARY KEY);
CREATE TABLE app.actors(id TEXT PRIMARY KEY, attribution TEXT NOT NULL);
CREATE TABLE app.memberships(household_id TEXT REFERENCES app.households,actor_id TEXT REFERENCES app.actors,role TEXT NOT NULL,PRIMARY KEY(household_id,actor_id));
CREATE TABLE app.owners(household_id TEXT REFERENCES app.households,id TEXT NOT NULL,display_name TEXT NOT NULL,PRIMARY KEY(household_id,id),UNIQUE(household_id,display_name));
CREATE TABLE app.accounts(household_id TEXT NOT NULL,id TEXT NOT NULL,owner_id TEXT NOT NULL,source_scope TEXT NOT NULL,identity_status TEXT NOT NULL CHECK(identity_status IN ('known','unresolved')),PRIMARY KEY(household_id,id),FOREIGN KEY(household_id,owner_id) REFERENCES app.owners(household_id,id));
CREATE TABLE app.migration_runs(id TEXT PRIMARY KEY,source_sha256 TEXT NOT NULL UNIQUE,exported_at TIMESTAMPTZ NOT NULL,source_counts JSONB NOT NULL,source_envelope TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- Received evidence replica inside the application boundary. Original ownership moves to ingestion in F4.
CREATE TABLE app.received_sources(run_id TEXT REFERENCES app.migration_runs,id TEXT NOT NULL,household_id TEXT REFERENCES app.households,source_table TEXT NOT NULL,original TEXT NOT NULL,sha256 TEXT NOT NULL,source_ordinal BIGINT NOT NULL,PRIMARY KEY(run_id,id));
CREATE TABLE app.household_state(household_id TEXT PRIMARY KEY REFERENCES app.households,facts_revision BIGINT NOT NULL DEFAULT 0,latest_version TEXT);
CREATE TABLE app.snapshots(run_id TEXT REFERENCES app.migration_runs,household_id TEXT NOT NULL,id TEXT NOT NULL,owner_id TEXT NOT NULL,account_id TEXT NOT NULL,effective_date DATE NOT NULL,known_at TIMESTAMPTZ NOT NULL,source_type TEXT NOT NULL,scope_status TEXT NOT NULL DEFAULT 'unresolved',PRIMARY KEY(run_id,household_id,id),FOREIGN KEY(household_id,account_id) REFERENCES app.accounts(household_id,id));
CREATE TABLE app.events(household_id TEXT NOT NULL,id TEXT NOT NULL,owner_id TEXT NOT NULL,account_id TEXT NOT NULL,instrument_code TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('BRL','USD')),side TEXT NOT NULL CHECK(side IN ('buy','sell')),quantity app.exact_decimal NOT NULL CHECK(quantity>0),unit_price app.exact_decimal NOT NULL CHECK(unit_price>0),fees_minor BIGINT NOT NULL CHECK(fees_minor>=0),effective_date DATE NOT NULL,settlement_date DATE,known_at TIMESTAMPTZ NOT NULL,evidence_id TEXT NOT NULL,application_status TEXT NOT NULL CHECK(application_status IN ('evidence_only','applied')),PRIMARY KEY(household_id,id),FOREIGN KEY(household_id,account_id) REFERENCES app.accounts(household_id,id));
CREATE TABLE app.event_legs(household_id TEXT NOT NULL,event_id TEXT NOT NULL,leg_no INTEGER NOT NULL,kind TEXT NOT NULL,currency TEXT NOT NULL,quantity app.exact_decimal,amount_minor BIGINT,PRIMARY KEY(household_id,event_id,leg_no),FOREIGN KEY(household_id,event_id) REFERENCES app.events(household_id,id));
CREATE TABLE app.proposals(household_id TEXT NOT NULL,id TEXT NOT NULL,owner_id TEXT NOT NULL,account_id TEXT NOT NULL,instrument_code TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('BRL','USD')),side TEXT NOT NULL CHECK(side IN ('buy','sell')),quantity app.exact_decimal NOT NULL CHECK(quantity>0),unit_price app.exact_decimal NOT NULL CHECK(unit_price>0),fees_minor BIGINT NOT NULL CHECK(fees_minor>=0),effective_date DATE NOT NULL,version INTEGER NOT NULL DEFAULT 1,summary_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','applied','rejected')),source_message_id TEXT,applied_event_id TEXT,PRIMARY KEY(household_id,id),FOREIGN KEY(household_id,account_id) REFERENCES app.accounts(household_id,id));
CREATE TABLE app.command_results(household_id TEXT REFERENCES app.households,actor_id TEXT REFERENCES app.actors,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,result JSONB NOT NULL,PRIMARY KEY(household_id,actor_id,idempotency_key));
CREATE TABLE app.holdings(household_id TEXT NOT NULL,account_id TEXT NOT NULL,instrument_code TEXT NOT NULL,currency TEXT NOT NULL,quantity app.exact_decimal NOT NULL,coverage_status TEXT NOT NULL CHECK(coverage_status IN ('verified','unresolved')),PRIMARY KEY(household_id,account_id,instrument_code,currency),FOREIGN KEY(household_id,account_id) REFERENCES app.accounts(household_id,id));
CREATE TABLE app.audit_log(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,household_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT NOT NULL,details JSONB NOT NULL,recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(household_id,actor_id) REFERENCES app.memberships(household_id,actor_id));
CREATE TABLE app.portfolio_versions(household_id TEXT NOT NULL REFERENCES app.households,id TEXT NOT NULL,run_id TEXT REFERENCES app.migration_runs,facts_revision BIGINT NOT NULL,market_revision TEXT NOT NULL,calculation_version TEXT NOT NULL,effective_as_of DATE NOT NULL,known_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ NOT NULL DEFAULT now(),view JSONB NOT NULL,PRIMARY KEY(household_id,id));
CREATE TABLE app.conversation_archives(run_id TEXT REFERENCES app.migration_runs,household_id TEXT REFERENCES app.households,id TEXT NOT NULL,origin TEXT NOT NULL,original TEXT NOT NULL,PRIMARY KEY(run_id,household_id,id));
